dashboard.definition:
{
  "title": "PulseForge · Application baseline and flow-duration drift",
  "description": "Did flow duration or volume to a destination drift away from its earlier baseline?",
  "inputs": {
    "input_global_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-24h@h,now"
      }
    },
    "input_run": {
      "type": "input.dropdown",
      "title": "Scenario run",
      "options": {
        "token": "run_tok",
        "defaultValue": "*",
        "items": [
          {
            "label": "All runs",
            "value": "*"
          }
        ],
        "createSearchJobOnChange": false,
        "clearDefaultOnSelection": false
      },
      "dataSources": {
        "primary": "ds_runs"
      },
      "context": {}
    },
    "input_index": {
      "type": "input.text",
      "title": "Index",
      "options": {
        "token": "index_tok",
        "defaultValue": "dev_test_replay"
      }
    },
    "input_st": {
      "type": "input.text",
      "title": "Sourcetype",
      "options": {
        "token": "st_tok",
        "defaultValue": "netflow:collector"
      }
    },
    "input_base_pct": {
      "type": "input.text",
      "title": "Baseline = first N % of window",
      "options": {
        "token": "base_pct",
        "defaultValue": "40"
      }
    },
    "input_ratio_tok": {
      "type": "input.text",
      "title": "Flag when observed/baseline ≥",
      "options": {
        "token": "ratio_tok",
        "defaultValue": "1.5"
      }
    },
    "input_dest_tok": {
      "type": "input.text",
      "title": "Destination (* = all)",
      "options": {
        "token": "dest_tok",
        "defaultValue": "*"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "viz_1": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### **PulseForge** · NetFlow/IPFIX · NOC-05\n**Application baseline and flow-duration drift**  ·  `NF-NOC-05-BASELINE-DRIFT`\n\n**Question:** Did flow duration or volume to a destination drift away from its earlier baseline?\n\n**Limits:** Flow duration is not application latency. It also depends on session length and exporter timeouts. The baseline is simply the first part of the selected window.",
        "fontColor": "#ececea",
        "backgroundColor": "#17191b",
        "fontSize": "default"
      }
    },
    "viz_2": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#22262a",
        "majorColor": "#c9786f",
        "majorFontSize": 40,
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "numberPrecision": 2
      },
      "title": "Largest duration ratio",
      "dataSources": {
        "primary": "ds_1"
      },
      "showProgressBar": true
    },
    "viz_3": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#22262a",
        "majorColor": "#d4764f",
        "majorFontSize": 40,
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "numberPrecision": 0
      },
      "title": "Destinations flagged",
      "dataSources": {
        "primary": "ds_2"
      },
      "showProgressBar": true
    },
    "viz_4": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#22262a",
        "majorColor": "#d4764f",
        "majorFontSize": 40,
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "numberPrecision": 0
      },
      "title": "Flow records",
      "dataSources": {
        "primary": "ds_3"
      },
      "showProgressBar": true
    },
    "viz_5": {
      "type": "splunk.table",
      "options": {
        "backgroundColor": "#22262a",
        "count": 6
      },
      "title": "Baseline vs observed per destination",
      "dataSources": {
        "primary": "ds_4"
      },
      "showProgressBar": true,
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "index=$index_tok$ sourcetype=$st_tok$ source=\"netspout:netflow:normalized\" netspout_scenario_id=\"NF-NOC-05-BASELINE-DRIFT\" netspout_run_id=\"$run_tok$\" dest=$dest_tok$ dest=\"$row.dest.value$\" | sort 0 _time | head 1000",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_6": {
      "type": "splunk.line",
      "options": {
        "backgroundColor": "#22262a",
        "seriesColors": [
          "#d4764f",
          "#6f9db5",
          "#c9a24a",
          "#6fa387",
          "#a79fc4",
          "#c9786f",
          "#8fb0a8",
          "#b8b09a"
        ],
        "legendDisplay": "bottom",
        "yAxisTitleText": "ms"
      },
      "title": "Average flow duration over time, by destination (ms)",
      "dataSources": {
        "primary": "ds_5"
      },
      "showProgressBar": true
    },
    "viz_7": {
      "type": "splunk.column",
      "options": {
        "backgroundColor": "#22262a",
        "seriesColors": [
          "#6f9db5",
          "#d4764f"
        ],
        "legendDisplay": "bottom"
      },
      "title": "Baseline vs observed average duration (ms)",
      "dataSources": {
        "primary": "ds_6"
      },
      "showProgressBar": true
    },
    "viz_8": {
      "type": "splunk.line",
      "options": {
        "backgroundColor": "#22262a",
        "seriesColors": [
          "#d4764f",
          "#6f9db5",
          "#c9a24a",
          "#6fa387",
          "#a79fc4",
          "#c9786f",
          "#8fb0a8",
          "#b8b09a"
        ],
        "legendDisplay": "bottom"
      },
      "title": "Total bytes over time, by destination",
      "dataSources": {
        "primary": "ds_7"
      },
      "showProgressBar": true
    },
    "viz_9": {
      "type": "splunk.bar",
      "options": {
        "backgroundColor": "#22262a",
        "seriesColors": [
          "#d4764f",
          "#6f9db5",
          "#c9a24a",
          "#6fa387",
          "#a79fc4",
          "#c9786f",
          "#8fb0a8",
          "#b8b09a"
        ],
        "legendDisplay": "bottom",
        "stackMode": "stacked"
      },
      "title": "Observed-period bytes by destination and port (port-based app label)",
      "dataSources": {
        "primary": "ds_8"
      },
      "showProgressBar": true
    },
    "viz_10": {
      "type": "splunk.table",
      "options": {
        "backgroundColor": "#22262a",
        "count": 5
      },
      "title": "Flow evidence (longest 100)",
      "dataSources": {
        "primary": "ds_9"
      },
      "showProgressBar": true
    },
    "viz_11": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "**Data prerequisites.** Events: index `$index_tok$`, sourcetype `$st_tok$`, source `netspout:netflow:normalized`, scenario `NF-NOC-05-BASELINE-DRIFT`, filtered by run (`netspout_run_id`). Flows are synthetic (RFC 5737 documentation addresses); `label_meta` is scenario truth, not exporter data. Fields used: dest, dest_port, app, duration_ms, bytes. **If every panel is empty:** no run of this scenario is indexed in the selected time range and index. Start it from the PulseForge Use Case Explorer (Run scenario with live delivery monitor) and wait for Dashboard READY. CIM names (`src`, `dest`, `transport`) come from the app's props.conf; no accelerated data model is assumed.",
        "fontColor": "#ececea",
        "backgroundColor": "#22262a",
        "fontSize": "default"
      }
    }
  },
  "dataSources": {
    "ds_1": {
      "type": "ds.search",
      "name": "Largest duration ratio",
      "options": {
        "query": "index=$index_tok$ sourcetype=$st_tok$ source=\"netspout:netflow:normalized\" netspout_scenario_id=\"NF-NOC-05-BASELINE-DRIFT\" netspout_run_id=\"$run_tok$\" dest=$dest_tok$ | eventstats min(_time) as t0 max(_time) as t1 | eval period=if(_time < t0+(t1-t0)*$base_pct$/100,\"baseline\",\"observed\") | stats avg(duration_ms) as dur avg(bytes) as byt count as flows by dest period | eval dur=round(dur,0), byt=round(byt,0) | stats values(eval(if(period=\"baseline\",dur,null()))) as baseline_ms values(eval(if(period=\"observed\",dur,null()))) as observed_ms values(eval(if(period=\"baseline\",byt,null()))) as baseline_bytes values(eval(if(period=\"observed\",byt,null()))) as observed_bytes sum(flows) as flows by dest | eval duration_ratio=round(observed_ms/baseline_ms,2), bytes_ratio=round(observed_bytes/baseline_bytes,2) | stats max(duration_ratio) as v | fields v"
      }
    },
    "ds_2": {
      "type": "ds.search",
      "name": "Destinations flagged",
      "options": {
        "query": "index=$index_tok$ sourcetype=$st_tok$ source=\"netspout:netflow:normalized\" netspout_scenario_id=\"NF-NOC-05-BASELINE-DRIFT\" netspout_run_id=\"$run_tok$\" dest=$dest_tok$ | eventstats min(_time) as t0 max(_time) as t1 | eval period=if(_time < t0+(t1-t0)*$base_pct$/100,\"baseline\",\"observed\") | stats avg(duration_ms) as dur avg(bytes) as byt count as flows by dest period | eval dur=round(dur,0), byt=round(byt,0) | stats values(eval(if(period=\"baseline\",dur,null()))) as baseline_ms values(eval(if(period=\"observed\",dur,null()))) as observed_ms values(eval(if(period=\"baseline\",byt,null()))) as baseline_bytes values(eval(if(period=\"observed\",byt,null()))) as observed_bytes sum(flows) as flows by dest | eval duration_ratio=round(observed_ms/baseline_ms,2), bytes_ratio=round(observed_bytes/baseline_bytes,2) | where duration_ratio>=$ratio_tok$ | stats count as v | fields v"
      }
    },
    "ds_3": {
      "type": "ds.search",
      "name": "Flow records",
      "options": {
        "query": "index=$index_tok$ sourcetype=$st_tok$ source=\"netspout:netflow:normalized\" netspout_scenario_id=\"NF-NOC-05-BASELINE-DRIFT\" netspout_run_id=\"$run_tok$\" dest=$dest_tok$ | stats count as v | fields v"
      }
    },
    "ds_4": {
      "type": "ds.search",
      "name": "Baseline vs observed per destination",
      "options": {
        "query": "index=$index_tok$ sourcetype=$st_tok$ source=\"netspout:netflow:normalized\" netspout_scenario_id=\"NF-NOC-05-BASELINE-DRIFT\" netspout_run_id=\"$run_tok$\" dest=$dest_tok$ | eventstats min(_time) as t0 max(_time) as t1 | eval period=if(_time < t0+(t1-t0)*$base_pct$/100,\"baseline\",\"observed\") | stats avg(duration_ms) as dur avg(bytes) as byt count as flows by dest period | eval dur=round(dur,0), byt=round(byt,0) | stats values(eval(if(period=\"baseline\",dur,null()))) as baseline_ms values(eval(if(period=\"observed\",dur,null()))) as observed_ms values(eval(if(period=\"baseline\",byt,null()))) as baseline_bytes values(eval(if(period=\"observed\",byt,null()))) as observed_bytes sum(flows) as flows by dest | eval duration_ratio=round(observed_ms/baseline_ms,2), bytes_ratio=round(observed_bytes/baseline_bytes,2) | sort - duration_ratio | table dest baseline_ms observed_ms duration_ratio baseline_bytes observed_bytes bytes_ratio flows"
      }
    },
    "ds_5": {
      "type": "ds.search",
      "name": "Average flow duration over time, by destination (ms)",
      "options": {
        "query": "index=$index_tok$ sourcetype=$st_tok$ source=\"netspout:netflow:normalized\" netspout_scenario_id=\"NF-NOC-05-BASELINE-DRIFT\" netspout_run_id=\"$run_tok$\" dest=$dest_tok$ | bin _time span=20s | chart avg(duration_ms) over _time by dest limit=6 | makecontinuous _time span=20s"
      }
    },
    "ds_6": {
      "type": "ds.search",
      "name": "Baseline vs observed average duration (ms)",
      "options": {
        "query": "index=$index_tok$ sourcetype=$st_tok$ source=\"netspout:netflow:normalized\" netspout_scenario_id=\"NF-NOC-05-BASELINE-DRIFT\" netspout_run_id=\"$run_tok$\" dest=$dest_tok$ | eventstats min(_time) as t0 max(_time) as t1 | eval period=if(_time < t0+(t1-t0)*$base_pct$/100,\"baseline\",\"observed\") | stats avg(duration_ms) as dur avg(bytes) as byt count as flows by dest period | eval dur=round(dur,0), byt=round(byt,0) | stats values(eval(if(period=\"baseline\",dur,null()))) as baseline_ms values(eval(if(period=\"observed\",dur,null()))) as observed_ms values(eval(if(period=\"baseline\",byt,null()))) as baseline_bytes values(eval(if(period=\"observed\",byt,null()))) as observed_bytes sum(flows) as flows by dest | eval duration_ratio=round(observed_ms/baseline_ms,2), bytes_ratio=round(observed_bytes/baseline_bytes,2) | table dest baseline_ms observed_ms"
      }
    },
    "ds_7": {
      "type": "ds.search",
      "name": "Total bytes over time, by destination",
      "options": {
        "query": "index=$index_tok$ sourcetype=$st_tok$ source=\"netspout:netflow:normalized\" netspout_scenario_id=\"NF-NOC-05-BASELINE-DRIFT\" netspout_run_id=\"$run_tok$\" dest=$dest_tok$ | bin _time span=20s | chart sum(bytes) over _time by dest limit=6 | makecontinuous _time span=20s | fillnull value=0"
      }
    },
    "ds_8": {
      "type": "ds.search",
      "name": "Observed-period bytes by destination and port (port-based app label)",
      "options": {
        "query": "index=$index_tok$ sourcetype=$st_tok$ source=\"netspout:netflow:normalized\" netspout_scenario_id=\"NF-NOC-05-BASELINE-DRIFT\" netspout_run_id=\"$run_tok$\" dest=$dest_tok$ | eventstats min(_time) as t0 max(_time) as t1 | eval period=if(_time < t0+(t1-t0)*$base_pct$/100,\"baseline\",\"observed\") | where period=\"observed\" | eval svc=coalesce(app,\"unclassified\").\" :\".dest_port | stats sum(bytes) as bytes by dest svc | eval KB=round(bytes/1000,0) | chart sum(KB) over dest by svc"
      }
    },
    "ds_9": {
      "type": "ds.search",
      "name": "Flow evidence (longest 100)",
      "options": {
        "query": "index=$index_tok$ sourcetype=$st_tok$ source=\"netspout:netflow:normalized\" netspout_scenario_id=\"NF-NOC-05-BASELINE-DRIFT\" netspout_run_id=\"$run_tok$\" dest=$dest_tok$ | sort - duration_ms | head 100 | eval start=strftime(flowStartMilliseconds/1000,\"%H:%M:%S\") | foreach app tcp_flags_text [eval <<FIELD>>=if(isnull(<<FIELD>>) OR <<FIELD>>=\"null\",\"-\",<<FIELD>>)] | table start exporter_ip src src_port dest dest_port transport app tcp_flags_text dscp packets bytes duration_ms snmp_in snmp_out label_meta.is_malicious"
      }
    },
    "ds_runs": {
      "type": "ds.search",
      "name": "Run list",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"NF-NOC-05-BASELINE-DRIFT\" | stats latest(_time) as t count by netspout_run_id | sort - t | eval label=netspout_run_id.\" · \".strftime(t,\"%m-%d %H:%M\").\" · \".count.\" flows\" | table label netspout_run_id"
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_global_time",
      "input_run",
      "input_index",
      "input_st",
      "input_base_pct",
      "input_ratio_tok",
      "input_dest_tok"
    ],
    "layoutDefinitions": {
      "layout_1": {
        "type": "absolute",
        "options": {
          "width": 1460,
          "height": 1250,
          "display": "auto-scale",
          "backgroundColor": "#17191b"
        },
        "structure": [
          {
            "item": "viz_1",
            "type": "block",
            "position": {
              "x": 20,
              "y": 0,
              "w": 1420,
              "h": 124
            }
          },
          {
            "item": "viz_2",
            "type": "block",
            "position": {
              "x": 20,
              "y": 134,
              "w": 300,
              "h": 120
            }
          },
          {
            "item": "viz_3",
            "type": "block",
            "position": {
              "x": 340,
              "y": 134,
              "w": 300,
              "h": 120
            }
          },
          {
            "item": "viz_4",
            "type": "block",
            "position": {
              "x": 660,
              "y": 134,
              "w": 300,
              "h": 120
            }
          },
          {
            "item": "viz_5",
            "type": "block",
            "position": {
              "x": 980,
              "y": 134,
              "w": 460,
              "h": 300
            }
          },
          {
            "item": "viz_6",
            "type": "block",
            "position": {
              "x": 20,
              "y": 274,
              "w": 940,
              "h": 270
            }
          },
          {
            "item": "viz_7",
            "type": "block",
            "position": {
              "x": 20,
              "y": 564,
              "w": 460,
              "h": 280
            }
          },
          {
            "item": "viz_8",
            "type": "block",
            "position": {
              "x": 500,
