            }
          },
          {
            "item": "viz_11",
            "type": "block",
            "position": {
              "x": 20,
              "y": 1134,
              "w": 1420,
              "h": 96
            }
          }
        ]
      }
    },
    "tabs": {
      "items": [
        {
          "label": "Application baseline and flow-duration drift",
          "layoutId": "layout_1"
        }
      ]
    }
  },
  "expressions": {},
  "applicationProperties": {
    "hideEdit": false,
    "hideExport": false
  }
}
